(()=>{'use strict';const state={os:'',uuid:'',build:null,source:'user'},get=()=>({...state});let builds=[],ready=null;const norm=v=>String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
function load(){return ready||(ready=fetch('knowledge/kb.json').then(r=>r.json()).then(data=>{const ref=data.find(e=>e.id==='REF-02');builds=(ref?.player_fix||[]).flatMap(line=>[...line.matchAll(/GTA5\s+([A-F0-9]{8})\b/g)].map(m=>({uuid:m[1],label:line.split(':')[0].replace(/, CURRENT/g,''),platform:/Mac app\s*$/.test(line.slice(0,m.index))?'macOS':'iOS / iPadOS',compat:line.match(/compat built ([^;]+)/)?.[1]||'',line})));return builds;}).catch(()=>[]));}
function match(uuid){const n=norm(uuid);return builds.find(b=>n.startsWith(b.uuid))||null;}
function setUUID(id,source='user'){state.uuid=id.toUpperCase();state.build=match(id);state.source=source;sync();}
function summary(){return [state.os||'OS not specified',state.build?state.build.label+' · '+state.uuid:state.uuid?'Unknown build · '+state.uuid:'Build not specified'].join(' · ');}
async function consume(q){await load();const os=String(q).match(/\b(iOS|iPadOS|macOS)\s*(\d{1,2}(?:\.\d{1,2}){0,2})\b/i),ids=[...String(q).matchAll(/(?:GTA5\s+(?:UUID\s*)?|UUID\s*[:=]?\s*)([a-f0-9]{8}(?:-[a-f0-9-]{4,})?)\b/ig)],bare=String(q).trim().match(/^([a-f0-9]{8}(?:-[a-f0-9-]{4,})?)$/i);if(os){state.os=os[1]+' '+os[2];state.source='user';}const id=ids[0]?.[1]||bare?.[1];if(id)setUUID(id);if(os)sync();if((os||id)&&q.trim().split(/\s+/).length<=9){return{text:id?(state.build?`Build identified from XDE's release list: ${state.build.label} (${state.build.platform}). GTA5 UUID prefix: ${state.build.uuid}.`:'This UUID is not in the supplied developer list. I will keep it as unverified; please include the compat built line or the full log.')+(state.os?'\n\nOS recorded: '+state.os+'.':'')+'\n\nWhat happens when you launch or play? If this follows an earlier issue, attach the log so we can check the actual failure.':`OS recorded: ${state.os}. I will use this for the current support session. Which build are you using, and what happens just before the issue?`,grounded:true,topic:'support-context'};}return null;}
async function ingestLog(text){await load();const matchOS=text.match(/\b(iOS|iPadOS|macOS)\s*(\d{1,2}(?:\.\d{1,2}){0,2})\b/i);if(matchOS)state.os=matchOS[1]+' '+matchOS[2];const uuid=text.match(/GTA5\s+(?:UUID\s*[:=]?\s*)?([a-f0-9]{8}(?:-[a-f0-9-]{4,})?)/i);if(uuid)setUUID(uuid[1],'log');sync();}
function sync(){const buildSelect=document.querySelector('#helper-build');if(buildSelect)buildSelect.value=state.build?.uuid||'';const family=document.querySelector('#helper-os-family');if(family&&state.os){const f=state.os.split(' ')[0].toLowerCase();family.value=f==='macos'?'macOS':f==='ipados'?'iPadOS':'iOS';}const major=document.querySelector('#helper-os-major');if(major&&state.os){const v=state.os.match(/\d+/)?.[0];major.value=['16','17','18','26','27'].includes(v)?v:'other';}const s=document.querySelector('.helper-support-summary');if(s)s.textContent=summary();const os=document.querySelector('#helper-os-exact'),uuid=document.querySelector('#helper-uuid');if(os&&document.activeElement!==os)os.value=state.os.replace(/^(iOS|iPadOS|macOS)\s*/i,'');if(uuid&&document.activeElement!==uuid)uuid.value=state.uuid;}
function init(){const form=document.querySelector('.ask-franklin-form');if(!form)return;const section=document.createElement('details');section.className='helper-support-details';section.innerHTML='<summary>Build details <span class="helper-support-summary">OS and build not specified</span></summary><div class="helper-support-fields"><label>Operating system<select id="helper-os-family"><option>iOS</option><option>iPadOS</option><option>macOS</option></select></label><label>OS version<select id="helper-os-major"><option value="">Not sure</option><option>16</option><option>17</option><option>18</option><option>26</option><option>27</option><option value="other">Other</option></select></label><label>Exact version (optional)<input id="helper-os-exact" inputmode="decimal" placeholder="e.g. 27.2" maxlength="12"></label><label>App / launcher build<select id="helper-build"><option value="">Not sure</option></select></label><label>GTA5 UUID or prefix (optional)<input id="helper-uuid" placeholder="e.g. 32BC6458" maxlength="36" autocapitalize="characters" spellcheck="false"></label><p>Build choices come from the developer list. The GTA5 binary ID identifies the app build, not your device. A shared UUID can have different graphics layers. Your selected OS is self-reported; log values take priority when found.</p></div>';form.before(section);load().then(list=>{const select=section.querySelector('#helper-build');list.forEach(b=>{const option=document.createElement('option');option.value=b.uuid;option.textContent=b.label+' · '+b.platform+' · '+b.uuid;select.append(option);});});section.querySelector('#helper-build').onchange=e=>setUUID(e.target.value);section.querySelector('#helper-uuid').onchange=e=>{const value=e.target.value.trim();if(value&&!/^[a-f0-9]{8}(?:-[a-f0-9-]{4,})?$/i.test(value)){e.target.setCustomValidity('Enter the 8-character prefix or full UUID from your GTA5 log.');e.target.reportValidity();return;}e.target.setCustomValidity('');setUUID(value);};const update=()=>{const exact=section.querySelector('#helper-os-exact'),v=exact.value.trim();if(v&&!/^\d{1,2}(?:\.\d{1,2}){0,2}$/.test(v)){exact.setCustomValidity('Use a version such as 18.2 or 27.2.');exact.reportValidity();return;}exact.setCustomValidity('');state.os=v?section.querySelector('#helper-os-family').value+' '+v:'';state.source='user';sync();};section.querySelector('#helper-os-exact').onchange=update;section.querySelector('#helper-os-family').onchange=update;section.querySelector('#helper-os-major').onchange=e=>{section.querySelector('#helper-os-exact').value=/^\d+$/.test(e.target.value)?e.target.value:'';update();};
const messages=document.querySelector('.ask-franklin-messages');let scheduled=false;const decorate=()=>{scheduled=false;messages.querySelectorAll('.bot .bubble').forEach(bubble=>{const walker=document.createTreeWalker(bubble,NodeFilter.SHOW_TEXT),nodes=[];let n;while(n=walker.nextNode())if(!n.parentElement.closest('button,a'))nodes.push(n);for(const node of nodes){const re=/\b[A-F0-9]{8}(?:-[A-F0-9]{4}-[A-F0-9]{4}-[A-F0-9]{4}-[A-F0-9]{12})?\b/g;const matches=[...node.textContent.matchAll(re)];if(!matches.length)continue;const frag=document.createDocumentFragment();let end=0;for(const m of matches){frag.append(document.createTextNode(node.textContent.slice(end,m.index)));const btn=document.createElement('button');btn.type='button';btn.className='helper-copy-uuid';btn.textContent=m[0];btn.setAttribute('aria-label','Copy UUID '+m[0]);btn.onclick=async()=>{try{await navigator.clipboard.writeText(m[0]);btn.textContent='Copied';setTimeout(()=>btn.textContent=m[0],1300);}catch{btn.textContent='Select to copy';btn.style.userSelect='text';}};frag.append(btn);end=m.index+m[0].length;}frag.append(document.createTextNode(node.textContent.slice(end)));node.replaceWith(frag);}});};if(messages)new MutationObserver(()=>{if(!scheduled){scheduled=true;requestAnimationFrame(decorate);}}).observe(messages,{subtree:true,childList:true,characterData:true});sync();}
window.FranklinSupportContext={load,get,consume,ingestLog,summary,match};if(document.querySelector('.ask-franklin-form'))init();else{const o=new MutationObserver(()=>{if(document.querySelector('.ask-franklin-form')){o.disconnect();init();}});o.observe(document.body,{childList:true,subtree:true});}})();
